inputs = ['gvez', 'wgfed', 'fegyu', 'jf', 'ye']
outputs = ['gvez', 'aigfed', 'fegyfj', 'jf', 'ye']

print("Input -> Output:")
for i in range(len(inputs)):
    print(f"'{inputs[i]}' -> '{outputs[i]}'")

# Let's look at character-by-character differences
for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]
    print(f"\n{inp} vs {out}:")
    if len(inp) != len(out):
        print(f"Length diff: {len(inp)} -> {len(out)}")
    else:
        for j in range(max(len(inp), len(out))):
            if j < len(inp) and j < len(out):
                if inp[j] != out[j]:
                    print(f"  Position {j}: '{inp[j]}' -> '{out[j]}'")
            elif j < len(inp):
                print(f"  Position {j}: '{inp[j]}' (removed)")
            elif j < len(out):
                print(f"  Position {j}: (added) '{out[j]}'")

